  "content": "1|export type SandboxTestRequest = {
2|  method: string;
3|  body: unknown;
4|  query: Record<string, unknown>;
5|  params: Record<string, string>;
6|  headers: Record<string, unknown>;
7|};
8|
9|/** Reserved Test Console envelope keys — other top-level keys are treated as POST/PUT body fields. */
10|export const TEST_PAYLOAD_ENVELOPE_KEYS = new Set(['body', 'query', 'params', 'headers']);
11|
12|export const extractBodyFieldsFromTestPayload = (
13|  payload: Record<string, unknown>,
14|): Record<string, unknown> => {
15|  if (payload.body && typeof payload.body === 'object' && !Array.isArray(payload.body)) {
16|    return payload.body as Record<string, unknown>;
17|  }
18|
19|  return Object.fromEntries(
20|    Object.entries(payload).filter(([key]) => !TEST_PAYLOAD_ENVELOPE_KEYS.has(key)),
21|  );
22|};
23|
24|/** Test Console payload: body fields at root; optional `query` / `params` wrappers when needed. */
25|export const buildRequestFromTestPayload = (
26|  method: string,
27|  payload: Record<string, unknown>,
28|): SandboxTestRequest => {
29|  const hasEnvelope = 'body' in payload || 'query' in payload || 'params' in payload;
30|  if (hasEnvelope) {
31|    return {
32|      method,
33|      body: payload.body ?? {},
34|      query: payload.query && typeof payload.query === 'object' && !Array.isArray(payload.query)
35|        ? payload.query as Record<string, unknown>
36|        : {},
37|      params: payload.params && typeof payload.params === 'object' && !Array.isArray(payload.params)
38|        ? Object.fromEntries(
39|          Object.entries(payload.params as Record<string, unknown>).map(([key, value]) => [key, String(value)]),
40|        )
41|        : {},
42|      headers: {},
43|    };
44|  }
45|
46|  return {
47|    method,
48|    body: payload,
49|    query: {},
50|    params: {},
51|    headers: {},
52|  };
53|};
